head.script:
// gridView.advancedExcelUpload(options) 의 options.popupUrl 로 지정하는 커스텀 Excel 파일 선택 팝업 화면
//  - 엔진 기본 팝업창(uiplugin/grid/upload/advancedfileUpload.html) 대신 이 화면이 열리는지 확인하는 용도
//  - 실제 업로드까지 수행하려면 엔진 규약(파일 input + __uploadForm__ 전송 + returnData 처리)에 맞게 구현해야 한다
scwin.onpageload = function() {
    txt_param.setValue("advancedExcelUpload 가 전달한 파라미터 : " + scwin.getUploadParam());
};

// advancedExcelUpload 가 이 화면으로 전달한 업로드 정보를 문자열로 반환한다.
//  · WFrame 레이어로 열린 경우 QueryString 이 아닌 팝업 파라미터(popupParam)로 전달된다.
//  · 별도 팝업창으로 열린 경우 팝업 경로 뒤에 QueryString 으로 전달된다.
scwin.getUploadParam = function() {
    if ($p.isWFramePopup() === true) {
        var strParam = $p.getPopupParam("popupParam");
        if (strParam === undefined || strParam === null || strParam === "") return "없음";

        var objParam = JSON.parse(strParam);
        return "gridID=" + objParam.gridID + " , dataList=" + objParam.dataList + " , columnIds=" + objParam.columnIds + " , wframe=" + objParam.wframe;
    }

    var strQuery = document.location.search;
    if (strQuery.charAt(0) === "?") strQuery = strQuery.substring(1);

    var arrParam = strQuery.split("&");
    var arrResult = [];
    for (var i = 0; i < arrParam.length; i++) {
        if (arrParam[i] === "") continue;
        arrResult.push(decodeURIComponent(arrParam[i]));
    }

    return (arrResult.length === 0 ? "없음" : arrResult.join(" , "));
};

// 닫기
//  · 이 화면은 wframe 값에 따라 화면 내 WFrame 레이어 또는 별도 팝업창으로 열리므로 열린 형태를 판별하여 닫는다.
//  · WFrame 레이어는 부모 화면과 window 를 공유하므로 window.close() 를 호출하면 부모 화면 자체가 닫힌다.
//  · 엔진 기본 팝업 화면과 동일하게 WFrame 레이어는 $p.getFrame().getParent().close(),
//    별도 팝업창은 window.self.close() 로 닫는다.
scwin.btn_closeSelf_onclick = function() {
    var objFrame = $p.getFrame();
    var objParent = (objFrame === null || objFrame === undefined) ? null : objFrame.getParent();

    if (objParent !== null && objParent !== undefined && typeof objParent.close === "function") {
        objParent.close();
    } else {
        window.self.close();
    }
};
